import{_ as t,c as o,o as a,aj as n}from"./chunks/framework.BlveriQe.js";const p=JSON.parse('{"title":"Interface: DocumentSyncStateChangedEvent","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/DocumentSyncStateChangedEvent.md","filePath":"reference/js-bao-wss-client/api/interfaces/DocumentSyncStateChangedEvent.md"}'),c={name:"reference/js-bao-wss-client/api/interfaces/DocumentSyncStateChangedEvent.md"};function s(r,e,d,i,h,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / DocumentSyncStateChangedEvent</p><h1 id="interface-documentsyncstatechangedevent" tabindex="-1">Interface: DocumentSyncStateChangedEvent <a class="header-anchor" href="#interface-documentsyncstatechangedevent" aria-label="Permalink to “Interface: DocumentSyncStateChangedEvent”">​</a></h1><p>Payload of the <code>documentSyncStateChanged</code> event (<code>client.on(&quot;documentSyncStateChanged&quot;, ...)</code>). Fired when a remote update for an open document is applied to it, reporting <code>state: &quot;synced&quot;</code> — so a loader that needs to reload on every remote write can subscribe here instead of observing the underlying document directly.</p><p>It also fires with <code>state: &quot;error&quot;</code> when an open document cannot be kept in sync:</p><ul><li>a remote update for it arrives but cannot be fetched or applied, which leaves the document behind the server;</li><li>its sync handshake goes unanswered for the whole handshake budget (<code>sync.handshakeTimeoutMs</code>, default 10s), so what the app is rendering has stopped converging. The client keeps retrying underneath, at a backoff that caps at 15s, and repeats <code>&quot;error&quot;</code> on each timeout it hits. Once such a document does sync, the event fires <code>&quot;synced&quot;</code> once more so the app can clear whatever it surfaced — but not for a completion that only scheduled a stale-local-state reset, since that document still has no server state.</li></ul><p>It does not fire at all for updates addressed to a document this client does not have open.</p><p><code>state</code> also carries <code>&quot;syncing&quot;</code> and <code>&quot;stale&quot;</code> for cross-client compatibility; this client emits only <code>&quot;synced&quot;</code> and <code>&quot;error&quot;</code>. For a document&#39;s overall caught-up/behind state, use the <code>sync</code> event (<a href="./SyncEvent.html">SyncEvent</a>), which fires on both transitions.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="documentid" tabindex="-1">documentId <a class="header-anchor" href="#documentid" aria-label="Permalink to “documentId”">​</a></h3><blockquote><p><strong>documentId</strong>: <code>string</code></p></blockquote><hr><h3 id="state" tabindex="-1">state <a class="header-anchor" href="#state" aria-label="Permalink to “state”">​</a></h3><blockquote><p><strong>state</strong>: <code>&quot;error&quot;</code> | <code>&quot;syncing&quot;</code> | <code>&quot;synced&quot;</code> | <code>&quot;stale&quot;</code></p></blockquote>',15)])])}const m=t(c,[["render",s]]);export{p as __pageData,m as default};
